always @(posedge clk) begin
	if (c == 4'h0) begin
		q <= b;
	end else if (c == 4'h1) begin
		q <= e;
	end else if (c == 4'h2) begin
		q <= a;
	end else if (c == 4'h3) begin
		q <= d;
	end else begin
		q <= 4'hf;
	end
end

endmodule

